import java.util.Objects;
class Person {
    String firstName, lastName; int age;
    Person(String f, String l, int a) { firstName = f; lastName = l; age = a; }
    public int hashCode() { return Objects.hash(firstName, lastName, age); }
    int manualHashCode() { return 31 * (31 * firstName.hashCode() + lastName.hashCode()) + age; }
}

