class CaseInsensitiveString {
    String value;
    CaseInsensitiveString(String v) { value = v; }
    public boolean equals(Object obj) {
        if (obj instanceof CaseInsensitiveString c) return value.equalsIgnoreCase(c.value);
        if (obj instanceof String s) return value.equalsIgnoreCase(s);
        return false;
    }
}

public static void main(String[] args) {
    CaseInsensitiveString cis = new CaseInsensitiveString("HELLO");
    System.out.println(cis.equals("hello")); // true
    System.out.println("hello".equals(cis)); // false - String.equals nie zna CaseInsensitiveString - LAMIE symetrycznosc
}

class Matrix implements Cloneable {
    int[][] data;
    Matrix(int[][] d) { data = d; }
    public Matrix clone() {
        int[][] copy = new int[data.length][];
        for (int i = 0; i < data.length; i++) copy[i] = data[i].clone();
        return new Matrix(copy);
    }
}

public static void main(String[] args) {
    Matrix m1 = new Matrix(new int[][]{{1,2},{3,4}});
    Matrix m2 = m1.clone();
    m2.data[0][0] = 99;
    System.out.println(m1.data[0][0] + " vs " + m2.data[0][0]);
    // clone() jest problematyczne: brak wywolania konstruktora, latwo o plytka kopie, checked CloneNotSupportedException
}

import java.util.*;
class SimpleHashSet {
    List<String>[] buckets = new List[16];
    void add(String s) { int b = Math.abs(s.hashCode()) % 16; if (buckets[b] == null) buckets[b] = new ArrayList<>(); if (!buckets[b].contains(s)) buckets[b].add(s); }
    boolean contains(String s) { int b = Math.abs(s.hashCode()) % 16; return buckets[b] != null && buckets[b].contains(s); }
}

public static void main(String[] args) {
    SimpleHashSet set = new SimpleHashSet();
    for (int i = 0; i < 100; i++) set.add("item" + (i % 30));
    System.out.println(set.contains("item5"));
}

import java.util.*;
class SimpleHashMap {
    List<Object[]>[] buckets = new List[16];
    void put(String key, int value) { int b = Math.abs(key.hashCode()) % 16; if (buckets[b] == null) buckets[b] = new ArrayList<>(); buckets[b].add(new Object[]{key, value}); }
    Integer get(String key) { int b = Math.abs(key.hashCode()) % 16; if (buckets[b] == null) return null; for (Object[] pair : buckets[b]) if (pair[0].equals(key)) return (Integer) pair[1]; return null; }
}

public static void main(String[] args) {
    SimpleHashMap map = new SimpleHashMap();
    map.put("a", 1); map.put("b", 2);
    System.out.println(map.get("a") + " " + map.get("b"));
}

