class LoggingProxy {
    Object target;
    LoggingProxy(Object t) { target = t; }
    public String toString() { return target.toString(); }
    public boolean equals(Object obj) { return obj instanceof LoggingProxy p ? target.equals(p.target) : target.equals(obj); }
    public int hashCode() { return target.hashCode(); }
}

public static void main(String[] args) {
    String original = "dane";
    LoggingProxy proxy = new LoggingProxy(original);
    System.out.println(proxy.equals(original)); // true - delegacja
}

public static void main(String[] args) {
    Integer a = 127, b = 127;
    System.out.println(a == b); // true - w cache
    Integer c = 128, d = 128;
    System.out.println(c == d); // false - poza cache, dwa rozne obiekty
    String s1 = "hello", s2 = "hello";
    System.out.println(s1 == s2); // true - String pool (interning)
    String s3 = new String("hello");
    System.out.println(s1 == s3); // false - new String() tworzy NOWY obiekt poza pool
}

class Version implements Comparable<Version> {
    int major, minor, patch;
    Version(int ma, int mi, int p) { major = ma; minor = mi; patch = p; }
    public int compareTo(Version o) {
        if (major != o.major) return Integer.compare(major, o.major);
        if (minor != o.minor) return Integer.compare(minor, o.minor);
        return Integer.compare(patch, o.patch);
    }
    public String toString() { return major + "." + minor + "." + patch; }
}

public static void main(String[] args) {
    Version[] versions = { new Version(1,2,0), new Version(2,0,0), new Version(1,9,5) };
    java.util.Arrays.sort(versions);
    System.out.println(java.util.Arrays.toString(versions));
}

