class Fast {
    int v; Fast(int v) { this.v = v; }
    public boolean equals(Object obj) { if (this == obj) return true; if (!(obj instanceof Fast f)) return false; return v == f.v; }
}

public static void main(String[] args) {
    Fast a = new Fast(5), b = new Fast(5);
    long start = System.nanoTime();
    for (int i = 0; i < 10_000_000; i++) a.equals(b);
    System.out.println((System.nanoTime() - start) + "ns");
    // Rekomendacja: pisz CZYTELNY, POPRAWNY equals (this==obj, null-check, getClass/instanceof) -
    // JIT i tak zoptymalizuje typowe przypadki, przedwczesna optymalizacja nie jest tu uzasadniona
}
